import json
import sys
from pathlib import Path

from pydantic import BaseModel, Field

from .paths import CONFIG_FILE, CONNECTION_FILE, CONTEST_DIR


class Settings(BaseModel):
    poll_interval_seconds: float = Field(default=5.0, gt=0)
    config_poll_seconds: float = Field(default=60.0, gt=0)
    host: str = "127.0.0.1"
    port: int = 8000
    # HTTP Basic password for /api/v4/ (username is fixed to "admin").
    # Generated by the setup GUI; the service entry point refuses to start
    # without it. Model-level default is empty so setup.py can load settings
    # before a password exists.
    api_password: str = ""
    # PTA rate limiting (task 14; live 429 storm 2026-10-14): global
    # request spacing on the PTA client + per-round detail budget.
    # detail_fetch_per_round ge=0 (0 = escape hatch: no detail fetches);
    # fetch_details false is a second, coarser escape hatch.
    pta_requests_per_second: float = Field(default=2.0, gt=0)
    detail_fetch_per_round: int = Field(default=5, ge=0)
    fetch_details: bool = True
    # persisted PTA snapshot cache (task 28): a restart serves the last
    # snapshot before the first live poll instead of re-fetching every
    # detail, which eliminates the 429 storm on restart. Disabled → the
    # cache file is never read or written.
    cache_enabled: bool = True
    cache_ttl_seconds: float = Field(default=3600.0, gt=0)
    # PTA request spacing jitter (task 28): each gate interval is extended
    # by uniform(0, jitter * min_interval); only ever adds to the spacing.
    pta_request_jitter: float = Field(default=0.25, ge=0, le=1)


def _fail(msg: str) -> None:
    print(f"config error: {msg}", file=sys.stderr)
    raise SystemExit(1)


def load_settings(path: Path = CONFIG_FILE) -> Settings:
    """Read manual/config/config.json; a missing file means all-default
    settings, while a present file must parse and validate strictly."""
    if not path.exists():
        return Settings()
    try:
        raw = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as e:
        _fail(f"invalid JSON in {path}: {e}")
        raise
    try:
        return Settings.model_validate(raw)
    except Exception as e:
        _fail(f"invalid config in {path}: {e}")
        raise


def load_connection(contest_dir: Path = CONTEST_DIR) -> dict[str, str] | None:
    """Read contest_dir/setup-connection.json (written by the setup GUI).

    Returns {"contest_id": ..., "pta_cookie": ...} only when both are
    non-empty strings; missing file, malformed JSON, or incomplete fields
    give None — never raises, the caller decides how to fail.
    """
    path = contest_dir / CONNECTION_FILE.name
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):  # JSONDecodeError + UnicodeDecodeError
        return None
    if not isinstance(data, dict):
        return None
    contest_id = data.get("contest_id")
    pta_cookie = data.get("pta_cookie")
    if not isinstance(contest_id, str) or not contest_id:
        return None
    if not isinstance(pta_cookie, str) or not pta_cookie:
        return None
    out: dict[str, str] = {"contest_id": contest_id, "pta_cookie": pta_cookie}
    # optional PRINT_SERVER URL (print pipeline); missing/empty/non-str →
    # omitted, existing validation untouched
    print_server = data.get("print_server")
    if isinstance(print_server, str) and print_server:
        out["print_server"] = print_server
    return out


_ID_SECTIONS = ("groups", "organizations", "teams", "problems", "languages")


def load_manual(contest_dir: Path = CONTEST_DIR) -> dict:
    """Merge every ``manual/contest/*.json`` override file (sorted)."""
    merged: dict = {
        "contest": None,
        "groups": {},
        "organizations": {},
        "teams": {},
        "problems": {},
        "languages": {},
        "judgement_types_overrides": {},
        # non-section top-level options from manual files (task 20): e.g.
        # print_problem ("1-3" | null) in setup-problems.json, which the
        # poller reads to drop that problem's data before translate
        "options": {},
    }
    if not contest_dir.exists():
        return merged
    for f in sorted(contest_dir.glob("*.json")):
        try:
            data = json.loads(f.read_text(encoding="utf-8"))
        except json.JSONDecodeError as e:
            _fail(f"invalid JSON in {f}: {e}")
        if not isinstance(data, dict):
            _fail(f"manual file {f} must contain a JSON object")
        contest = data.get("contest")
        if isinstance(contest, dict):
            if merged["contest"] is None:
                merged["contest"] = {}
            merged["contest"].update(contest)
        jt = data.get("judgement_types")
        if isinstance(jt, dict):
            overrides = jt.get("overrides", {})
            if not isinstance(overrides, dict):
                _fail(f"judgement_types.overrides in {f} must be an object")
            merged["judgement_types_overrides"].update(overrides)
        if "print_problem" in data:  # str label or null; later file wins
            merged["options"]["print_problem"] = data["print_problem"]
        for key in _ID_SECTIONS:
            section = data.get(key)
            if section is None:
                continue
            if isinstance(section, dict):
                for k, v in section.items():
                    if not isinstance(v, dict):
                        _fail(f"{key}.{k} in {f} must be an object")
                    if not isinstance(merged[key].get(k), (dict, type(None))):
                        _fail(
                            f"{key}.{k} in {f} conflicts with a non-object value "
                            "set by an earlier manual file"
                        )
                    merged[key].setdefault(k, {}).update(v)
            elif isinstance(section, list):
                for item in section:
                    if not isinstance(item, dict) or "id" not in item:
                        _fail(f"{key} list items in {f} must be objects with an id")
                    iid = item["id"]
                    merged[key].setdefault(iid, {}).update(
                        {k: v for k, v in item.items() if k != "id"}
                    )
            else:
                _fail(f"{key} in {f} must be an object or a list")
    return merged
